// Prototype: updates are stored per Slice in this browser, not a server permission system.
const updateStoreKey='slice-updates-v1';
const updateSeeds={
 'manual-chat':[{id:'manual-intro',kind:'Release notes',title:'You can now ask the manual',body:'Ask about brightness, power, or the warranty. Each answer includes the source passage so you can check it.\nMore example questions are planned.',date:'2026-09-20T08:00:00Z'}],
 orbit:[{id:'orbit-event',kind:'Event',title:'This week: find your favorite orbit',body:'Adjust gravity and watch the orbits change. Capture a favorite moment and share your settings with friends.\nThis is a demo event. No registration needed.',eventDate:'2026-09-27',date:'2026-09-20T07:00:00Z'},{id:'orbit-update',kind:'Release notes',title:'Gravity Lab · Exploration tips',body:'Start at 1.0× and adjust gravity a little at a time to compare the orbits.\nThe browser experience is playable. The desktop edition is a concept demo.',date:'2026-09-19T08:00:00Z'}],
 city:[{id:'city-news',kind:'Announcement',title:'Welcome to Micro City',body:'Find news about the city experiment here. Try adjusting taxes in your browser. The full download is not available yet.',date:'2026-09-20T06:00:00Z'}]
};
function updatesFor(id){const data=readStored(updateStoreKey,{});const list=data&&Array.isArray(data[id])?data[id]:(updateSeeds[id]||[]);return list.map(x=>x&&({...x,kind:({'\u66f4\u65b0\u8bf4\u660e':'Release notes','\u6d3b\u52a8':'Event','\u516c\u544a':'Announcement'})[x.kind]||x.kind})).filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.body==='string'&&['Release notes','Event','Announcement'].includes(x.kind))}
function storeUpdates(id,list){try{const data=readStored(updateStoreKey,{});const safe=data&&typeof data==='object'&&!Array.isArray(data)?data:{};localStorage.setItem(updateStoreKey,JSON.stringify({...safe,[id]:list}));return true}catch{toast('Could not save. Check your browser storage.');return false}}
let updateWorkId=null,updateManaging=false,updateEditing=null,removedUpdate=null;
const updateSection=document.createElement('section');updateSection.id='slice-updates';
function updateDate(d){const date=new Date(d);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('en')}
function renderSliceUpdates(){const w=works.find(x=>x.id===updateWorkId);if(!w)return;const list=updatesFor(w.id).filter(x=>!x.deleted).sort((a,b)=>new Date(b.date)-new Date(a.date));updateSection.innerHTML=`<div class="updates-heading"><div><span class="eyebrow">FROM THE SLICER</span><h3>News and updates <small>${list.length}</small></h3><p>From ${escapeHtml(w.author)} </p></div><button id="manage-updates">${updateManaging?'Done':w.local?'Manage updates':'Try creator controls'}</button></div><p class="updates-local">${w.local?'Local creator view':'Demo content · Try creator controls'} · Changes stay in this browser. Account permissions and sync are not connected yet.</p>${updateManaging?'<button id="add-slice-update" class="update-add">＋ Add an update</button>':''}<form id="slice-update-form" hidden><h4 id="update-form-title">Add an update</h4><div class="update-form-row"><label>Type<select name="kind"><option>Release notes</option><option>Event</option><option>Announcement</option></select></label><label id="update-event-field" hidden>Event date (optional)<input type="date" name="eventDate"></label></div><label>Title<input name="title" required maxlength="80" placeholder="What is new?"></label><label>Message<textarea name="body" required maxlength="4000" rows="5" placeholder="Share release notes, event details, or news about this experience…"></textarea></label><p id="update-form-error" role="alert"></p><div class="update-form-actions"><button type="button" id="cancel-slice-update">Cancel</button><button type="submit" class="dark">Save update</button></div></form>${removedUpdate&&updateManaging?'<div class="update-undo" role="status">Update removed <button id="undo-slice-update">Undo</button></div>':''}<div class="updates-list">${list.map(u=>`<article class="update-card"><div class="update-meta"><span class="update-kind">${escapeHtml(u.kind)}</span><time>${escapeHtml(updateDate(u.date))}</time>${u.edited?'<span>Edited</span>':''}</div><h4>${escapeHtml(u.title)}</h4>${u.kind==='Event'&&u.eventDate?`<p class="update-event">Event date · ${escapeHtml(u.eventDate)}</p>`:''}<p class="update-body">${escapeHtml(u.body)}</p>${updateManaging?`<div class="update-card-actions"><button data-update-edit="${escapeHtml(u.id)}">Edit</button><button data-update-delete="${escapeHtml(u.id)}">Delete</button></div>`:''}</article>`).join('')||'<div class="updates-empty">No updates yet. Release notes and events will appear here.</div>'}</div>`;
 updateSection.querySelector('#manage-updates').onclick=()=>{updateManaging=!updateManaging;updateEditing=null;renderSliceUpdates()};updateSection.querySelector('#add-slice-update')?.addEventListener('click',()=>editSliceUpdate(null));updateSection.querySelector('#cancel-slice-update').onclick=()=>{updateEditing=null;updateSection.querySelector('form').hidden=true};const form=updateSection.querySelector('form');form.elements.kind.onchange=()=>{updateSection.querySelector('#update-event-field').hidden=form.elements.kind.value!=='Event'};form.onsubmit=e=>{e.preventDefault();if(!updateManaging)return;const title=form.elements.title.value.trim(),body=form.elements.body.value.trim();if(!title||!body){updateSection.querySelector('#update-form-error').textContent='Enter a title and message.';return}const all=updatesFor(w.id),old=all.find(x=>x.id===updateEditing),entry={id:old?.id||crypto.randomUUID(),kind:form.elements.kind.value,title,body,eventDate:form.elements.kind.value==='Event'?form.elements.eventDate.value:'',date:old?.date||new Date().toISOString(),edited:!!old};const next=old?all.map(x=>x.id===old.id?entry:x):[entry,...all];if(storeUpdates(w.id,next)){updateEditing=null;renderSliceUpdates();toast('Update saved locally.')}};
 updateSection.querySelectorAll('[data-update-edit]').forEach(b=>b.onclick=()=>editSliceUpdate(b.dataset.updateEdit));updateSection.querySelectorAll('[data-update-delete]').forEach(b=>b.onclick=()=>{const all=updatesFor(w.id),entry=all.find(x=>x.id===b.dataset.updateDelete);if(storeUpdates(w.id,all.map(x=>x.id===entry.id?{...x,deleted:true}:x))){removedUpdate=entry;renderSliceUpdates()}});updateSection.querySelector('#undo-slice-update')?.addEventListener('click',()=>{if(storeUpdates(w.id,updatesFor(w.id).map(x=>x.id===removedUpdate.id?removedUpdate:x))){removedUpdate=null;renderSliceUpdates()}});
}
function editSliceUpdate(id){updateEditing=id;const form=updateSection.querySelector('form'),entry=updatesFor(updateWorkId).find(x=>x.id===id);form.reset();for(const field of ['kind','title','body','eventDate'])if(entry)form.elements[field].value=entry[field]||'';form.hidden=false;form.elements.kind.onchange();updateSection.querySelector('#update-form-title').textContent=id?'Edit update':'Add an update';form.elements.title.focus();form.scrollIntoView({behavior:'smooth',block:'nearest'})}
function attachSliceUpdates(id){updateWorkId=id;updateManaging=false;updateEditing=null;removedUpdate=null;document.querySelector('#dialog-stage').after(updateSection);renderSliceUpdates()}
const updatesOpenBefore=openWork;openWork=function(id,remix=false){updatesOpenBefore(id,remix);if(dialog.open&&!remix){attachSliceUpdates(id)}else updateSection.remove()};if(dialog.open&&!remixing)attachSliceUpdates(activeId);
